export function avatarWindowClipPath(size: number): string {
  const scale = size / BASE_SIZE;
  const scaled = WINDOW_PATH.replace(/-?d+(?:.d+)?/g, (n) => (Number(n) * scale).toFixed(2));
  return `path('${scaled}')`;
}
